using Serilog.Core; using Serilog.Events; namespace KKBOT.Observability.Logging; public sealed class LogEnricher : ILogEventEnricher { private readonly string _key; private readonly object _value; public LogEnricher(string key, object value) { _key = key; _value = value; } public void Enrich(LogEvent logEvent, ILogEventPropertyFactory propertyFactory) { var prop = propertyFactory.CreateProperty(_key, _value); logEvent.AddPropertyIfAbsent(prop); } }